import type { Transition } from 'motion/react';

/**
 * The only springs in the app (design system: Motion): a toy with weight. `--ease-press`, `--ease-settle` and
 * `--ease-wobble` in `index.css` are these same springs, generated by Motion's `spring(visualDuration, bounce)`, so CSS
 * and JS move alike. Change one, regenerate the other.
 */
export const SPRING = {
  /** A control under the finger. */
  press: { type: 'spring', visualDuration: 0.16, bounce: 0.3 },
  /** Comes to rest with no overshoot. The only one allowed in a calm zone. */
  settle: { type: 'spring', visualDuration: 0.28, bounce: 0 },
  /** A small toy reacting to a touch. */
  wobble: { type: 'spring', visualDuration: 0.35, bounce: 0.45 },
  /** The wind-up of a real win. */
  windup: { type: 'spring', visualDuration: 0.6, bounce: 0.35 },
} as const satisfies Record<string, Transition>;
